"""COR AVANÇADA (23/11, dono): nós de cor ligados, balanço de branco pelo conta-gotas, rodas, curvas, LOG, LUT (.cube importar/criar), escopos.
Confere a CONTA no pixel (motor) e a TELA (criar nó, ligar pela porta, soltar, preset, roda, curva, celular)."""
import sys, os, json
exec(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "teste_video_fluidez.py")).read().split("with sync_playwright() as p:")[0].replace("PORTA = 8897", "PORTA = 8925"))
F = [0]
def ok(c, t):
    print(("  ✓ " if c else "  ✗ ") + t)
    if not c: F[0] += 1
CL = "__video.P().clips"
# motor: aplica um grafo numa cor lisa e devolve o pixel do meio
MOTOR = """(async (a) => { const c=document.createElement('canvas'); c.width=64; c.height=36; const x=c.getContext('2d'); x.fillStyle=a.cor; x.fillRect(0,0,64,36);
  const r=BWCorNos.aplicar(c,64,36,a.g,{sempre:true}); if(!r) return null; const t=document.createElement('canvas'); t.width=64; t.height=36; const y=t.getContext('2d'); y.drawImage(r,0,0,64,36); const d=y.getImageData(32,18,1,1).data; return [d[0],d[1],d[2]]; })"""
def grafo(*nos): return "BWCorNos.linha(%s)" % json.dumps(list(nos))
def px(pg, cor, g): return pg.evaluate("(async()=>{return await (" + MOTOR + ")({cor:'" + cor + "',g:" + g + "})})()")
COR = "(()=>{const c=document.getElementById('veCv'),x=c.getContext('2d'),d=x.getImageData(Math.round(c.width/2),Math.round(c.height/2),4,4).data;return [d[0],d[1],d[2]]})()"
with sync_playwright() as p:
    b = p.chromium.launch(args=["--no-sandbox"])
    ctx = b.new_context(viewport={"width": 1280, "height": 800}, service_workers="block", accept_downloads=True); ctx.route("**/*", rota)
    pg = ctx.new_page(); er = []; pg.on("pageerror", lambda e: er.append(str(e))); pg.on("dialog", lambda d: d.accept(d.default_value or "Teste"))
    pg.goto(BASE + "video.html"); pg.wait_for_function("window.__veProntoOk === true", timeout=15000)
    ok(pg.evaluate("!!window.BWCorNos && BWCorNos.suporta()"), "motor de cor em WebGL disponível (%s bits)" % pg.evaluate("BWCorNos.bits()"))
    # ── a conta ──
    a = px(pg, "rgb(100,100,100)", grafo(["cont", {"expo": 50}])); ok(a and 190 <= a[0] <= 210, f"exposição +1 ponto dobra a luz (100 → {a})")
    a = px(pg, "rgb(200,60,60)", grafo(["sat", {"sat": -100}])); ok(a and max(a) - min(a) <= 2, f"saturação −100 = cinza ({a})")
    a = px(pg, "rgb(64,64,64)", grafo(["cont", {"cont": 100, "pivo": 50}])); ok(a and a[0] < 10, f"contraste em volta do pivô escurece o que está abaixo dele ({a})")
    a = px(pg, "rgb(120,120,120)", grafo(["prim", {"gain": [1, 0, 0]}])); ok(a and a[0] > a[1] + 20 and a[0] > a[2] + 20, f"roda GAIN puxada para o vermelho ({a})")
    a = px(pg, "rgb(30,30,30)", grafo(["logw", {"alta": [1, 0, 0.5]}])); b2 = px(pg, "rgb(230,230,230)", grafo(["logw", {"alta": [1, 0, 0.5]}]))
    ok(a and abs(a[0] - 30) <= 2 and b2[0] > 240, f"roda Log ALTAS mexe só no claro (escuro {a}, claro {b2})")
    a = px(pg, "rgb(128,128,128)", grafo(["curv", {"y": [[0, 0], [0.5, 0.8], [1, 1]]}])); ok(a and 198 <= a[0] <= 210, f"curva: meio levado a 80% ({a})")
    a = px(pg, "rgb(105,105,105)", grafo(["log", {"perfil": "slog3"}])); ok(a and 105 <= a[0] <= 130, f"S-Log3: cinza médio (41%) sai perto de 45% ({a})")
    a2 = px(pg, "rgb(100,100,100)", grafo(["log", {"perfil": "logc3"}])); a3 = px(pg, "rgb(108,108,108)", grafo(["log", {"perfil": "apple"}])); a4 = px(pg, "rgb(101,101,101)", grafo(["log", {"perfil": "dlog"}]))
    ok(all(v and 95 <= v[0] <= 140 for v in (a2, a3, a4)), f"LogC3, Apple Log e D-Log: cinza médio de cada perfil cai no meio (ARRI {a2}, Apple {a3}, DJI {a4})")
    a = px(pg, "rgb(100,100,100)", grafo(["cont", {"expo": 50}, 50])); ok(a and 140 <= a[0] <= 160, f"mistura do nó em 50% = metade do efeito ({a})")
    a = px(pg, "rgb(100,100,100)", "(()=>{const g=" + grafo(["cont", {"expo": 50}]) + ";g.nos[0].off=true;return g})()"); ok(a and abs(a[0] - 100) <= 1, "nó desligado não mexe na imagem")
    a = px(pg, "rgb(100,100,100)", "(()=>{const g=" + grafo(["cont", {"expo": 50}]) + ";g.lig=[['in','out']];return g})()"); ok(a and abs(a[0] - 100) <= 1 and not pg.evaluate("BWCorNos.ativo((()=>{const g=" + grafo(["cont", {"expo": 50}]) + ";g.lig=[['in','out']];return g})())"), "nó fora do fluxo (sem ligação) não entra")
    # LUT: .cube que inverte as cores
    pg.evaluate("""(async()=>{let t='TITLE "inv"\\nLUT_3D_SIZE 5\\n';for(let b=0;b<5;b++)for(let g=0;g<5;g++)for(let r=0;r<5;r++)t+=(1-r/4)+' '+(1-g/4)+' '+(1-b/4)+'\\n';const l=BWCorNos.lerCube(t);const o=await BWCorNos.lutGuardar('inverte',l.n,l.dados);window.__lut=o.id})()""")
    a = px(pg, "rgb(200,100,40)", "BWCorNos.linha([['lut',{lut:window.__lut}]])"); ok(a and abs(a[0] - 55) <= 3 and abs(a[1] - 155) <= 3 and abs(a[2] - 215) <= 3, f"LUT .cube importada é aplicada (200,100,40 → {a})")
    r = pg.evaluate("(()=>{try{BWCorNos.lerCube('LUT_1D_SIZE 4\\n0 0 0\\n1 1 1');return 'passou'}catch(e){return e.message}})()"); ok("3D" in r, f"LUT 1D é recusada com o motivo ({r})")
    pg.evaluate("(async()=>{const g=" + grafo(["sat", {"sat": -100}], ["cont", {"expo": 25}]) + ";const l=BWCorNos.gerarLut(g,33);const o=await BWCorNos.lutGuardar('pb',l.n,l.dados);window.__lut2=o.id;window.__cube=BWCorNos.escreverCube('pb',l.n,l.dados)})()")
    direto = px(pg, "rgb(180,90,50)", grafo(["sat", {"sat": -100}], ["cont", {"expo": 25}])); pela = px(pg, "rgb(180,90,50)", "BWCorNos.linha([['lut',{lut:window.__lut2}]])")
    ok(direto and pela and max(abs(direto[i] - pela[i]) for i in range(3)) <= 4, f"CRIAR LUT DOS NÓS: a LUT dá a mesma cor dos nós ({direto} × {pela})")
    ok(pg.evaluate("window.__cube.indexOf('LUT_3D_SIZE 33')>0 && window.__cube.trim().split('\\n').length>=33*33*33"), ".cube gerado tem 33³ linhas")
    volta = pg.evaluate("(()=>{const l=BWCorNos.lerCube(window.__cube);return l.n})()"); ok(volta == 33, "o .cube criado é lido de volta")
    # ── a tela ──
    with pg.expect_file_chooser(timeout=5000) as fc: pg.click("#veImportar")
    fc.value.set_files([f"{TMP}/verde.webm", f"{TMP}/azul.webm"]); pg.wait_for_function("Object.keys(__video.MID).length>=2", timeout=15000); pg.wait_for_timeout(300)
    for k in range(2): pg.evaluate("document.querySelectorAll('#veLib [data-mid]')[%d].click()" % k); pg.wait_for_timeout(300)
    pg.evaluate("__video.irPara(1)"); pg.locator('[data-clip]').first.click(); pg.wait_for_timeout(300); antes = pg.evaluate(COR)
    pg.evaluate("document.querySelectorAll('#vePropCorpo [data-seta]').forEach(t=>{if(t.classList.contains('fechada'))t.click()})"); pg.wait_for_timeout(200)
    pg.locator('#vePropCorpo [data-acao="corNos"]').click(); pg.wait_for_timeout(500)
    ok(pg.locator("#cnTela").is_visible() and pg.locator('#cnPlano [data-no="in"]').is_visible() and pg.locator('#cnPlano [data-no="out"]').is_visible(), "🎛 COR AVANÇADA abre a área com ENTRADA e SAÍDA")
    pg.evaluate("BWCorNos.tela().inserir('sat')"); pg.wait_for_timeout(200); pg.evaluate("BWCorNos.tela().inserir('cont')"); pg.wait_for_timeout(300)
    ok(pg.locator("#cnPlano .cn-no:not(.fixo)").count() == 2 and len(pg.evaluate(f"BWCorNos.cadeia({CL}[0].nos)")) == 2, "＋ NÓ cria e já liga no fim do fluxo")
    pg.locator('#cnTela [data-a="mais"]').first.click(); pg.wait_for_timeout(250); ok(pg.locator(".bwf-menu").is_visible() and pg.locator(".bwf-menu button").count() >= 9, "＋ NÓ mostra os 9 tipos de nó"); pg.keyboard.press("Escape"); pg.wait_for_timeout(200)
    ok(pg.locator("#cnTela").is_visible(), "Esc do menu não fecha a área")
    ids = pg.evaluate(f"{CL}[0].nos.nos.map(n=>n.id)")
    pg.locator('#cnLado [data-p="expo"]').fill("60"); pg.wait_for_timeout(250)
    ok(pg.evaluate(f"{CL}[0].nos.nos[1].p.expo") == 60, "barra do nó escolhido grava no nó")
    # soltar a ligação tocando na linha e religar arrastando a porta
    n0 = pg.evaluate(f"{CL}[0].nos.lig.length"); pg.evaluate("document.querySelector('#cnFios [data-fio]').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,clientX:0,clientY:0}))"); pg.wait_for_timeout(250)
    ok(pg.evaluate(f"{CL}[0].nos.lig.length") == n0 - 1 and len(pg.evaluate(f"BWCorNos.cadeia({CL}[0].nos)")) == 0, "tocar na linha solta a ligação (o fluxo abre e a cor para de valer)")
    falta = pg.evaluate(f"(()=>{{const g={CL}[0].nos,de=['in'].concat(g.nos.map(n=>n.id)).find(a=>!g.lig.some(l=>l[0]===a)),para=g.nos.map(n=>n.id).concat(['out']).find(a=>!g.lig.some(l=>l[1]===a));return [de,para]}})()")
    s = pg.locator(f'#cnPlano [data-s="{falta[0]}"]').bounding_box(); e = pg.locator(f'#cnPlano [data-no="{falta[1]}"]').bounding_box()
    pg.mouse.move(s["x"] + 9, s["y"] + 9); pg.mouse.down(); pg.mouse.move(s["x"] + 40, s["y"] + 30, steps=4); pg.mouse.move(e["x"] + 30, e["y"] + 20, steps=8); pg.mouse.up(); pg.wait_for_timeout(300)
    ok(len(pg.evaluate(f"BWCorNos.cadeia({CL}[0].nos)")) == 2, f"arrastar da bolinha até o outro nó liga de novo ({falta})")
    # arrastar o nó
    nb = pg.locator(f'#cnPlano [data-no="{ids[0]}"]').bounding_box(); x0 = pg.evaluate(f"{CL}[0].nos.nos[0].y")
    pg.mouse.move(nb["x"] + 40, nb["y"] + 30); pg.mouse.down(); pg.mouse.move(nb["x"] + 60, nb["y"] + 120, steps=6); pg.mouse.up(); pg.wait_for_timeout(250)
    ok(pg.evaluate(f"{CL}[0].nos.nos[0].y") > x0 + 50, "o nó flutua: arrastar muda de lugar")
    # presets, rodas, curva
    pg.locator('#cnTela [data-a="presets"]').first.click(); pg.wait_for_timeout(200); pg.locator('#cnLado [data-pre]', has_text="Cinema azul e laranja").click(); pg.wait_for_timeout(300)
    ok([n["tipo"] for n in pg.evaluate(f"BWCorNos.cadeia({CL}[0].nos)")] == ["cont", "logw", "sat"], "preset 'Cinema azul e laranja' monta 3 nós ligados")
    idl = pg.evaluate(f"{CL}[0].nos.nos[1].id"); pg.evaluate(f"BWCorNos.tela().sel('{idl}')"); pg.wait_for_timeout(250)
    d = pg.locator('#cnLado [data-roda="meio"]').bounding_box(); pg.mouse.move(d["x"] + 52, d["y"] + 52); pg.mouse.down(); pg.mouse.move(d["x"] + 85, d["y"] + 52, steps=4); pg.mouse.up(); pg.wait_for_timeout(250)
    m = pg.evaluate(f"{CL}[0].nos.nos[1].p.meio"); ok(m[0] > 0.4 and abs(m[1]) < 0.15, f"arrastar o ponto da roda MEIOS para a direita ({m})")
    pg.locator('#cnLado [data-roda="meio"]').dblclick(); pg.wait_for_timeout(250); ok(pg.evaluate(f"{CL}[0].nos.nos[1].p.meio") == [0, 0, 0], "dois toques na roda zera")
    pg.evaluate("BWCorNos.tela().inserir('curv')"); pg.wait_for_timeout(300); cb = pg.locator("#cnCurva").bounding_box()
    pg.mouse.move(cb["x"] + cb["width"] * 0.5, cb["y"] + cb["height"] * 0.5); pg.mouse.down(); pg.mouse.move(cb["x"] + cb["width"] * 0.5, cb["y"] + cb["height"] * 0.3, steps=4); pg.mouse.up(); pg.wait_for_timeout(250)
    cy = pg.evaluate(f"{CL}[0].nos.nos.find(n=>n.tipo==='curv').p.y"); ok(len(cy) == 3 and 0.62 < cy[1][1] < 0.78, f"curva: clicar cria o ponto e arrastar levanta ({cy})")
    # balanço de branco pelo conta-gotas (take azul → clicar deixa neutro)
    pg.locator('#cnTela [data-a="limpar"]').click(); pg.wait_for_timeout(200); pg.evaluate("BWCorNos.tela().inserir('wb')"); pg.wait_for_timeout(250)
    pg.locator('#cnLado [data-a="gota"]').click(); pg.wait_for_timeout(200); vb = pg.locator("#cnCv").bounding_box(); pg.mouse.click(vb["x"] + vb["width"] / 2, vb["y"] + vb["height"] / 2); pg.wait_for_timeout(400)
    w = pg.evaluate(f"{CL}[0].nos.nos[0].p"); cor_v = pg.evaluate("(()=>{const c=document.getElementById('cnCv'),d=c.getContext('2d').getImageData(c.width>>1,c.height>>1,1,1).data;return [d[0],d[1],d[2]]})()")
    ok(w["gr"] > 1.5 and w["gg"] < 0.8 and max(cor_v) - min(cor_v) <= 30, f"🎯 CLICAR NO BRANCO: o ponto clicado (verde) fica neutro no visor ({cor_v}; ganhos {w['gr']}, {w['gg']}, {w['gb']})")
    # escopos e LUT pela tela
    esc = pg.evaluate("['cnEscW','cnEscP','cnEscV'].map(i=>{const c=document.getElementById(i),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let n=0;for(let k=0;k<d.length;k+=4)if(d[k]+d[k+1]+d[k+2]>120)n++;return n})")
    ok(all(v > 20 for v in esc), f"escopos desenhados: waveform, parade e vectorscope ({esc})")
    pg.locator('#cnTela [data-a="luts"]').first.click(); pg.wait_for_timeout(400); ok(pg.locator("#cnLado [data-lut]").count() >= 2 and pg.locator("#cnCube").count() == 1, "▦ LUTS lista as LUTs do aparelho e tem ⇪ IMPORTAR .CUBE")
    open(f"{TMP}/quente.cube", "w").write("TITLE \"q\"\nLUT_3D_SIZE 2\n" + "\n".join(f"{min(1,r*1.0)} {g*0.5} {bb*0.5}" for bb in (0, 1) for g in (0, 1) for r in (0, 1)) + "\n")
    pg.set_input_files("#cnCube", f"{TMP}/quente.cube"); pg.wait_for_timeout(500); ok(pg.locator("#cnLado [data-lut]", has_text="quente").count() == 1, "importar um .cube guarda a LUT no aparelho")
    pg.locator("#cnLado [data-lut]", has_text="quente").click(); pg.wait_for_timeout(300); ok(pg.evaluate(f"BWCorNos.cadeia({CL}[0].nos).some(n=>n.tipo==='lut'&&n.p.nome==='quente')"), "tocar na LUT põe ela num nó do fluxo")
    pg.locator('#cnTela .cn-topo [data-a="luts"]').click(); pg.wait_for_timeout(300)
    with pg.expect_download() as dl: pg.locator("#cnLado [data-lutb]").first.click()
    ok(dl.value.suggested_filename.endswith(".cube"), "⬇ baixa a LUT em .cube")
    pg.locator('#cnTela [data-a="voltar"]').click(); pg.wait_for_timeout(600); depois = pg.evaluate(COR)
    ok(not pg.locator("#cnTela").count() and sum(abs(antes[i] - depois[i]) for i in range(3)) > 40, f"‹ VOLTAR: a cor vale na prévia do editor ({antes} → {depois})")
    ok("nó(s)" in pg.locator('#vePropCorpo [data-acao="corNos"]').inner_text(), "o botão mostra quantos nós o take tem")
    pg.wait_for_timeout(700); pg.reload(); pg.wait_for_function("window.__veProntoOk === true", timeout=15000); pg.wait_for_timeout(1200)
    ok(pg.evaluate(f"!!{CL}[0].nos && BWCorNos.cadeia({CL}[0].nos).length>=2") and pg.evaluate("BWCorNos.luts().length") >= 3, "recarregou: os nós e as LUTs continuam")
    ok(not er, "sem erro de JavaScript " + str(er[:2])); ctx.close()
    # celular
    ctx = b.new_context(viewport={"width": 390, "height": 844}, has_touch=True, is_mobile=True, service_workers="block"); ctx.route("**/*", rota); pg = ctx.new_page(); er = []; pg.on("pageerror", lambda e: er.append(str(e)))
    pg.goto(BASE + "video.html"); pg.wait_for_function("window.__veProntoOk === true", timeout=15000); pg.wait_for_timeout(800)
    pg.set_input_files("#vaArq", [f"{TMP}/verde.webm"]); pg.wait_for_function("Object.keys(__video.MID).length>=1", timeout=20000); pg.wait_for_timeout(500)
    pg.evaluate("document.querySelector('#veLib [data-mid]').click()"); pg.wait_for_timeout(500); pg.evaluate("__video.corAvancada(__video.P().clips[0])"); pg.wait_for_timeout(500)
    ok(pg.locator("#cnTela").is_visible() and pg.locator(".cn-abas").is_visible() and pg.evaluate("document.documentElement.scrollWidth-document.documentElement.clientWidth") <= 0, "celular: área aberta com as abas NÓS · AJUSTES · ESCOPOS, sem estouro")
    pg.locator('#cnTela [data-a="presets"]').first.tap(); pg.wait_for_timeout(300); pg.locator('#cnLado [data-pre]').first.tap(); pg.wait_for_timeout(300)
    ok(pg.evaluate(f"BWCorNos.cadeia({CL}[0].nos).length") == 3, "celular: tocar num preset monta os nós")
    pg.locator('.cn-abas [data-aba="nos"]').tap(); pg.wait_for_timeout(200); pg.locator("#cnPlano .cn-no:not(.fixo)").nth(1).tap(); pg.wait_for_timeout(200); pg.locator('.cn-abas [data-aba="ajustes"]').tap(); pg.wait_for_timeout(250)
    ok(pg.locator('#cnLado [data-p="cont"]').is_visible(), "celular: tocar no nó e abrir AJUSTES mostra as barras dele")
